import React, { useState, useEffect } from "react";
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, Legend, Cell, CartesianGrid, PieChart, Pie } from "recharts";
import { ArrowTrendingUpIcon } from "@heroicons/react/24/solid";

const COLORS = ["#3b82f6", "#10b981", "#f59e42", "#f43f5e", "#6366f1", "#fbbf24", "#14b8a6"];

function getMonthsRemaining(deadline) {
  const now = new Date();
  const end = new Date(deadline);
  return Math.max(
    1,
    (end.getFullYear() - now.getFullYear()) * 12 + (end.getMonth() - now.getMonth())
  );
}

function getMonthlySavings(goal) {
  const months = getMonthsRemaining(goal.deadline);
  const amountLeft = Math.max(goal.amount - (goal.saved || 0), 0);
  return +(amountLeft / months).toFixed(2);
}

const Overview = ({ goals, income, currentSavings, plan }) => {
  const [chartData, setChartData] = useState([]);

  useEffect(() => {
    if (goals && plan) {
      const data = goals.map(goal => ({
        name: goal.name,
        monthly: plan.monthlyAllocations[goal.id] || 0,
        total: plan.totalAllocations[goal.id] || 0,
        target: goal.targetAmount,
        remaining: (goal.targetAmount - (plan.totalAllocations[goal.id] || 0))
      }));

      // Add total row
      data.push({
        name: 'Total',
        monthly: plan.totalMonthlyNeeded || 0,
        total: plan.totalSavingsNeeded || 0,
        target: goals.reduce((sum, goal) => sum + goal.targetAmount, 0),
        remaining: (plan.totalSavingsNeeded || 0) - (currentSavings || 0)
      });

      setChartData(data);
    }
  }, [goals, plan, currentSavings]);

  const totalTarget = goals.reduce((sum, goal) => sum + goal.amount, 0);
  const totalSaved = goals.reduce((sum, goal) => sum + (goal.saved || 0), 0);
  const totalSavingsNeeded = totalTarget - currentSavings;
  const monthlyDisposableIncome = income?.monthlyDisposableIncome || 0;
  const shortfall = monthlyDisposableIncome < (plan?.totalMonthlyNeeded || 0) 
    ? (plan?.totalMonthlyNeeded || 0) - monthlyDisposableIncome 
    : 0;

  const RADIAN = Math.PI / 180;
  const renderCustomizedLabel = ({ cx, cy, midAngle, innerRadius, outerRadius, percent, index }) => {
    const radius = innerRadius + (outerRadius - innerRadius) * 0.5;
    const x = cx + radius * Math.cos(-midAngle * RADIAN);
    const y = cy + radius * Math.sin(-midAngle * RADIAN);

    return (
      <text
        x={x}
        y={y}
        fill="white"
        textAnchor={x > cx ? 'start' : 'end'}
        dominantBaseline="central"
        className="text-sm font-medium"
      >
        {`${(percent * 100).toFixed(0)}%`}
      </text>
    );
  };

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <div className="bg-white p-4 rounded-lg shadow">
          <div className="text-sm text-gray-600">Total Savings Needed</div>
          <div className="text-2xl font-bold text-emerald-700">${totalSavingsNeeded.toLocaleString()}</div>
        </div>
        <div className="bg-white p-4 rounded-lg shadow">
          <div className="text-sm text-gray-600">Total Saved</div>
          <div className="text-2xl font-bold text-emerald-700">${currentSavings.toLocaleString()}</div>
        </div>
        <div className="bg-white p-4 rounded-lg shadow">
          <div className="text-sm text-gray-600">Monthly Income</div>
          <div className="text-2xl font-bold text-emerald-700">${monthlyDisposableIncome.toLocaleString()}</div>
        </div>
        <div className="bg-white p-4 rounded-lg shadow">
          <div className="text-sm text-gray-600">Monthly Savings Needed</div>
          <div className="text-2xl font-bold text-emerald-700">${(plan?.totalMonthlyNeeded || 0).toLocaleString()}</div>
        </div>
      </div>

      {shortfall > 0 && (
        <div className="bg-red-50 border border-red-200 rounded-lg p-4">
          <div className="text-red-800 font-medium">Monthly Income Shortfall</div>
          <div className="text-red-600">
            You need an additional ${shortfall.toLocaleString()} per month to meet your savings goals.
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white rounded-xl shadow-sm p-6 border border-gray-100">
          <h3 className="text-lg font-semibold text-gray-900 mb-4">Monthly Savings Allocation</h3>
          <div className="h-[400px]">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart
                data={chartData}
                margin={{ top: 20, right: 30, left: 20, bottom: 60 }}
                barGap={0}
              >
                <defs>
                  <linearGradient id="colorMonthly" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#10B981" stopOpacity={0.8}/>
                    <stop offset="95%" stopColor="#10B981" stopOpacity={0.2}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#E5E7EB" />
                <XAxis 
                  dataKey="name" 
                  angle={-45} 
                  textAnchor="end" 
                  height={60}
                  tick={{ fill: '#6B7280', fontSize: 12 }}
                  tickLine={false}
                />
                <YAxis 
                  tickFormatter={(value) => `$${value.toLocaleString()}`}
                  tick={{ fill: '#6B7280', fontSize: 12 }}
                  tickLine={false}
                  axisLine={false}
                />
                <Tooltip 
                  formatter={(value) => [`$${value.toLocaleString()}`, 'Monthly Savings']}
                  contentStyle={{
                    backgroundColor: 'white',
                    border: '1px solid #E5E7EB',
                    borderRadius: '8px',
                    boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)',
                  }}
                />
                <Legend 
                  verticalAlign="top" 
                  height={36}
                  wrapperStyle={{
                    paddingBottom: '20px'
                  }}
                />
                <Bar 
                  dataKey="monthly" 
                  name="Monthly Savings" 
                  fill="url(#colorMonthly)"
                  radius={[4, 4, 0, 0]}
                />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white rounded-xl shadow-sm p-6 border border-gray-100">
          <h3 className="text-lg font-semibold text-gray-900 mb-4">Total Savings Distribution</h3>
          <div className="h-[400px]">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <defs>
                  {COLORS.map((color, index) => (
                    <linearGradient key={index} id={`colorPie${index}`} x1="0" y1="0" x2="0" y2="1">
                      <stop offset="5%" stopColor={color} stopOpacity={0.8}/>
                      <stop offset="95%" stopColor={color} stopOpacity={0.2}/>
                    </linearGradient>
                  ))}
                </defs>
                <Pie
                  data={chartData}
                  cx="50%"
                  cy="50%"
                  labelLine={false}
                  label={renderCustomizedLabel}
                  outerRadius={150}
                  innerRadius={80}
                  paddingAngle={2}
                  dataKey="total"
                >
                  {chartData.map((entry, index) => (
                    <Cell 
                      key={`cell-${index}`} 
                      fill={`url(#colorPie${index})`}
                      stroke="white"
                      strokeWidth={2}
                    />
                  ))}
                </Pie>
                <Tooltip 
                  formatter={(value) => [`$${value.toLocaleString()}`, 'Total Savings']}
                  contentStyle={{
                    backgroundColor: 'white',
                    border: '1px solid #E5E7EB',
                    borderRadius: '8px',
                    boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)',
                  }}
                />
                <Legend 
                  layout="vertical" 
                  verticalAlign="middle" 
                  align="right"
                  wrapperStyle={{
                    paddingLeft: '20px'
                  }}
                />
              </PieChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      <div className="bg-white rounded-xl shadow p-8">
        <h2 className="text-2xl font-bold text-primary mb-4">Goal Summary</h2>
        <div className="space-y-4">
          {goals.map((goal) => (
            <div key={goal.id} className="border rounded-lg p-4">
              <div className="flex justify-between items-center">
                <div>
                  <div className="font-medium">{goal.name}</div>
                  <div className="text-sm text-gray-600">
                    Target: ${goal.amount.toLocaleString()}
                  </div>
                </div>
                <div className="text-right">
                  <div className="font-medium">
                    ${(goal.monthlySavings || 0).toLocaleString()}/month
                  </div>
                  <div className="text-sm text-gray-600">
                    {goal.monthsRemaining} months remaining
                  </div>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default Overview;
